import{J as n,o as s,c as a,K as t}from"./chunks/framework.BdCQ0ow3.js";const h=JSON.parse('{"title":"Spring Security 会话登录：身份如何跨请求保存","description":"沿一次登录和后续请求理解 SecurityFilterChain、Authentication、SecurityContext 与 Session，并说明自定义登录的显式保存边界。","frontmatter":{"title":"Spring Security 会话登录：身份如何跨请求保存","date":"2026-11-06T00:00:00.000Z","description":"沿一次登录和后续请求理解 SecurityFilterChain、Authentication、SecurityContext 与 Session，并说明自定义登录的显式保存边界。","category":"Java 后端","tags":["Spring Security","Session","Spring MVC","Java"],"folder":"java/highlights"},"headers":[{"level":2,"title":"安全过滤器在 Controller 之前工作","slug":"安全过滤器在-controller-之前工作","link":"#安全过滤器在-controller-之前工作","children":[]},{"level":2,"title":"登录同时解决凭据验证与状态建立","slug":"登录同时解决凭据验证与状态建立","link":"#登录同时解决凭据验证与状态建立","children":[]},{"level":2,"title":"自定义登录需要显式保存上下文","slug":"自定义登录需要显式保存上下文","link":"#自定义登录需要显式保存上下文","children":[]},{"level":2,"title":"下一次请求怎样找到同一个身份","slug":"下一次请求怎样找到同一个身份","link":"#下一次请求怎样找到同一个身份","children":[]},{"level":2,"title":"有 Session 也仍然需要关注请求来源","slug":"有-session-也仍然需要关注请求来源","link":"#有-session-也仍然需要关注请求来源","children":[]},{"level":2,"title":"参考与来源","slug":"参考与来源","link":"#参考与来源","children":[]}],"relativePath":"posts/spring-security-session.md","filePath":"posts/spring-security-session.md"}'),o={name:"posts/spring-security-session.md"};function l(i,e,r,p,c,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="spring-security-会话登录身份如何跨请求保存" tabindex="-1">Spring Security 会话登录：身份如何跨请求保存 <a class="header-anchor" href="#spring-security-会话登录身份如何跨请求保存" aria-label="Permalink to &quot;Spring Security 会话登录：身份如何跨请求保存&quot;">​</a></h1><p>用户名和密码验证通过之后，为什么下一次请求不需要再验证一遍？理解这个问题，需要把“验证本次凭据”和“保存后续可用的登录状态”分开看。前者产生认证结果，后者把认证结果与之后的请求关联起来。</p><p>本文以 Servlet 应用中的会话登录为例，关注 Spring Security 6 及之后常见的显式保存机制。JWT 等无状态认证使用不同的持久化策略，不能直接套用下面的 Session 流程。</p><h2 id="安全过滤器在-controller-之前工作" tabindex="-1">安全过滤器在 Controller 之前工作 <a class="header-anchor" href="#安全过滤器在-controller-之前工作" aria-label="Permalink to &quot;安全过滤器在 Controller 之前工作&quot;">​</a></h2><p>一个经过 Spring Security 的典型请求可以概括为：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>HTTP 请求</span></span>
<span class="line"><span>  → Servlet 过滤器链中的 DelegatingFilterProxy</span></span>
<span class="line"><span>  → FilterChainProxy</span></span>
<span class="line"><span>  → 选择匹配的 SecurityFilterChain，执行其中的过滤器</span></span>
<span class="line"><span>  → DispatcherServlet</span></span>
<span class="line"><span>  → Spring MVC 拦截器与 Controller</span></span>
<span class="line"><span>  → Service → Mapper</span></span></code></pre></div><p><code>SecurityFilterChain</code> 描述请求匹配条件以及要应用的安全过滤器。存在多条链时，由 <code>FilterChainProxy</code> 选择第一条匹配的链，不是把所有链中的规则全部叠加。所选链可以恢复身份、进行认证、校验 CSRF、防止未授权访问，也可能直接返回响应，不再进入 Controller。</p><p>Filter 属于 Servlet 请求处理机制，作用范围不限于 MVC Controller；MVC 的 <code>HandlerInterceptor</code> 则围绕已选择的处理器工作。它们与普通 Bean 的区别主要在参与请求处理的接入位置，不能简单理解为“普通 Bean 只在启动时有用，Filter 才会自动运行”。</p><h2 id="登录同时解决凭据验证与状态建立" tabindex="-1">登录同时解决凭据验证与状态建立 <a class="header-anchor" href="#登录同时解决凭据验证与状态建立" aria-label="Permalink to &quot;登录同时解决凭据验证与状态建立&quot;">​</a></h2><p>用户名密码认证的一条常见路径是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>接收登录凭据</span></span>
<span class="line"><span>  → 创建未认证的 Authentication</span></span>
<span class="line"><span>  → AuthenticationManager 委派给适合的 AuthenticationProvider</span></span>
<span class="line"><span>  → 查询用户并校验密码</span></span>
<span class="line"><span>  → 得到已认证的 Authentication</span></span>
<span class="line"><span>  → 应用会话认证策略</span></span>
<span class="line"><span>  → 创建、设置并保存 SecurityContext</span></span></code></pre></div><p><code>AuthenticationManager</code> 是认证入口，用户名密码场景通常由相应 Provider 配合 <code>UserDetailsService</code> 和 <code>PasswordEncoder</code> 完成。认证成功后得到的 <code>Authentication</code> 包含当前主体及权限信息；它不是让业务代码自己拼一个“已登录”标记来代替密码校验。</p><p><code>SecurityContext</code> 包含认证对象，<code>SecurityContextHolder</code> 提供当前执行上下文中的访问入口。常见 Servlet 配置使用线程关联的存储方式，因此设置 Holder 主要影响当前请求的处理，并不天然意味着下一个请求也能恢复这个身份。</p><h2 id="自定义登录需要显式保存上下文" tabindex="-1">自定义登录需要显式保存上下文 <a class="header-anchor" href="#自定义登录需要显式保存上下文" aria-label="Permalink to &quot;自定义登录需要显式保存上下文&quot;">​</a></h2><p>Spring Security 提供的标准认证流程会完成其配置要求的相关步骤。若自己在 Controller 或 Filter 中调用认证管理器，就需要明确负责会话策略与上下文持久化。</p><p>下面是顺序示意，省略异常响应、依赖声明和应用配置，不能作为完整登录接口直接复制运行：</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Authentication result </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> authenticationManager.</span><span style="color:#6F42C1;">authenticate</span><span style="color:#24292E;">(</span></span>
<span class="line"><span style="color:#24292E;">    UsernamePasswordAuthenticationToken.</span><span style="color:#6F42C1;">unauthenticated</span><span style="color:#24292E;">(</span></span>
<span class="line"><span style="color:#24292E;">        command.</span><span style="color:#6F42C1;">username</span><span style="color:#24292E;">(), command.</span><span style="color:#6F42C1;">password</span><span style="color:#24292E;">())</span></span>
<span class="line"><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">sessionStrategy.</span><span style="color:#6F42C1;">onAuthentication</span><span style="color:#24292E;">(result, request, response);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">SecurityContext context </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> SecurityContextHolder.</span><span style="color:#6F42C1;">createEmptyContext</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#24292E;">context.</span><span style="color:#6F42C1;">setAuthentication</span><span style="color:#24292E;">(result);</span></span>
<span class="line"><span style="color:#24292E;">SecurityContextHolder.</span><span style="color:#6F42C1;">setContext</span><span style="color:#24292E;">(context);</span></span>
<span class="line"><span style="color:#24292E;">contextRepository.</span><span style="color:#6F42C1;">saveContext</span><span style="color:#24292E;">(context, request, response);</span></span></code></pre></div><p>这里的 <code>contextRepository</code> 必须与安全过滤器使用的持久化配置一致；会话场景通常包含基于 HTTP Session 的仓库。只调用 <code>SecurityContextHolder.setContext()</code>，在采用 <code>SecurityContextHolderFilter</code> 的显式保存配置下，不能保证身份跨请求保留。</p><p>会话策略还可能包含会话固定攻击防护、并发会话控制和认证后的 CSRF 令牌处理。自定义认证入口应复用应用实际配置的策略，避免随意调用一个空策略就以为这些能力已经具备。具体组件组合需要根据所用版本和配置核对。</p><h2 id="下一次请求怎样找到同一个身份" tabindex="-1">下一次请求怎样找到同一个身份 <a class="header-anchor" href="#下一次请求怎样找到同一个身份" aria-label="Permalink to &quot;下一次请求怎样找到同一个身份&quot;">​</a></h2><p>浏览器通常携带名为 <code>JSESSIONID</code> 的会话 Cookie，名称也可以自定义。Cookie 主要携带会话标识，认证上下文保存在服务端会话存储中，并非每次都把用户名密码重新发送给应用。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>浏览器携带会话 Cookie</span></span>
<span class="line"><span>  → 服务端找到对应 Session</span></span>
<span class="line"><span>  → SecurityContextRepository 读取安全上下文</span></span>
<span class="line"><span>  → 安全过滤器使当前请求可取得 Authentication</span></span>
<span class="line"><span>  → 授权检查通过后进入 Controller</span></span></code></pre></div><p>因此 Controller 可以通过 Spring Security 提供的访问方式取得当前主体，也常见直接声明 <code>Authentication</code> 参数。业务层继续使用认证对象中的身份定位用户，不必让客户端再传一个可任意修改的用户 ID 来代表“我是谁”。</p><p>会话可能过期、被注销，或者当前请求只有匿名认证信息。不能仅凭“存在 Authentication 对象”就判断用户已经登录；应把访问限制交给相应的授权规则，并处理应用定义的未认证响应。请求结束后，安全过滤器还负责清理线程上的上下文，防止身份残留到复用的线程中。</p><p>身份恢复也不等于业务授权已经完成。例如某个接口允许登录用户访问，仍不意味着任意用户都能批准同一个项目的申请。服务端应结合当前认证身份与项目归属判断操作权限；客户端传入的项目编号只负责定位目标，不能成为权限证明。这能把安全链的通用访问规则与业务层的数据范围判断连接起来。</p><h2 id="有-session-也仍然需要关注请求来源" tabindex="-1">有 Session 也仍然需要关注请求来源 <a class="header-anchor" href="#有-session-也仍然需要关注请求来源" aria-label="Permalink to &quot;有 Session 也仍然需要关注请求来源&quot;">​</a></h2><p>浏览器会自动附带会话 Cookie，正是这种便利使会话认证需要考虑 CSRF。把接口改成接收 JSON，或把它标为 <code>permitAll()</code>，都不等于其他安全过滤器自动失效。是否要求 CSRF 令牌取决于请求和应用配置；不应仅为了让一个登录请求通过，就直接关闭整站防护。</p><p>调试“登录成功但下一次又未登录”时，可以顺着浏览器是否保存并发送 Cookie、服务端是否保存上下文、后续请求命中哪条安全链这条路径排查。跨域场景还要结合客户端凭据选项及 Cookie 属性判断，不能只检查认证接口有没有返回成功。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><p>本文整理自个人项目学习笔记，合并了安全过滤器链和会话认证相关记录。</p><ul><li><a href="https://docs.spring.io/spring-security/reference/servlet/architecture.html" target="_blank" rel="noreferrer">Spring Security：Servlet 安全架构与过滤器链选择</a></li><li><a href="https://docs.spring.io/spring-security/reference/servlet/authentication/session-management.html" target="_blank" rel="noreferrer">Spring Security：认证持久化与会话管理</a></li><li><a href="https://docs.spring.io/spring-security/reference/servlet/authentication/architecture.html" target="_blank" rel="noreferrer">Spring Security：Authentication 与 SecurityContext 架构</a></li></ul>`,31)])])}const y=n(o,[["render",l]]);export{h as __pageData,y as default};
